#include <furi.h>
#include <gui/gui.h>
#include <input/input.h>
#include <stdlib.h>
#include <stdio.h>
#define W 320
#define H 64
#define K(k) (1u<<InputKey##k)
typedef struct {uint8_t m[H][W]; int x,y,v,dir,stock,hair,shirt,mode,sel,t,cd; unsigned keys; bool run; FuriMutex* lock; FuriMessageQueue* q;} G;
static bool solid(G*g,int x,int y){return x<0||x>=W||y>=H||(y>=0&&g->m[y][x]&&g->m[y][x]!=6);}
static void player(Canvas*c,int x,int y,G*g){canvas_draw_box(c,x+1,y,6,2);if(g->hair==1)canvas_draw_box(c,x,y+1,2,5);if(g->hair==2)canvas_draw_box(c,x+2,y-2,4,2);canvas_draw_frame(c,x+1,y+2,6,4);canvas_draw_dot(c,x+(g->dir>0?5:2),y+3);canvas_draw_frame(c,x+2,y+6,4,4);if(g->shirt)canvas_draw_box(c,x+3,y+7,2,2);int a=(g->keys&(K(Left)|K(Right)))?(g->t/3)%2:0;canvas_draw_line(c,x+2,y+10,x+1+a,y+13);canvas_draw_line(c,x+5,y+10,x+6-a,y+13);canvas_draw_line(c,x+1,y+7,x,y+9);canvas_draw_line(c,x+6,y+7,x+7,y+9);}
static void draw(Canvas*c,void*p){G*g=p;furi_mutex_acquire(g->lock,FuriWaitForever);canvas_clear(c);canvas_set_font(c,FontSecondary);char s[40];if(g->mode==0){canvas_draw_str(c,30,9,"TERRARIA MINI");player(c,60,15,g);snprintf(s,sizeof(s),"%c Hair: %d",g->sel==0?'>':' ',g->hair+1);canvas_draw_str(c,8,39,s);snprintf(s,sizeof(s),"%c Shirt: %d",g->sel==1?'>':' ',g->shirt+1);canvas_draw_str(c,8,49,s);canvas_draw_str(c,8,61,"OK: Play   L/R: Change");}else if(g->mode==2){canvas_draw_str(c,40,15,"PAUSED");canvas_draw_str(c,15,32,"OK: Resume");canvas_draw_str(c,15,48,"Back: Exit");}else if(g->mode==3){snprintf(s,sizeof(s),"Inventory: %d blocks",g->stock);canvas_draw_str(c,4,20,s);canvas_draw_str(c,4,40,"OK / Back: Return");}else{int ox=g->x-15,oy=g->y-7;for(int j=0;j<14;j++)for(int i=0;i<32;i++){int x=ox+i,y=oy+j;if(x<0||x>=W||y<0||y>=H)continue;int a=i*4,b=j*4+8;uint8_t k=g->m[y][x];if(k==6){canvas_draw_line(c,a+1,b,a+1,b+3);canvas_draw_line(c,a,b+1,a+3,b+1);}else if(k){canvas_draw_box(c,a,b,4,4);canvas_set_color(c,ColorWhite);if(k==1||k==3)canvas_draw_dot(c,a+1,b+1);if(k==4)canvas_draw_line(c,a,b,a+3,b);if(k==5)canvas_draw_line(c,a,b+3,a+3,b);if(k==7)canvas_draw_dot(c,a+2,b+2);canvas_set_color(c,ColorBlack);}}player(c,58,24,g);int tx=60+g->dir*4;canvas_draw_frame(c,tx,40,4,4);const char* names[]={"Forest","Desert","Snow","Jungle"};snprintf(s,sizeof(s),"%s B:%d %s",names[g->x/80],g->stock,(g->keys&K(Down))?"BUILD":"MINE");canvas_draw_str(c,0,7,s);}furi_mutex_release(g->lock);}
static void input(InputEvent*e,void*p){G*g=p;furi_message_queue_put(g->q,e,0);}
static void world(G*g){int h=25;for(int x=0;x<W;x++){int b=x/80;if(x%3==0)h+=rand()%3-1;if(h<20)h=20;if(h>30)h=30;for(int y=h;y<H;y++){g->m[y][x]=y<h+4?(b==0?1:b==1?3:b==2?4:5):2;if(y>h+5&&rand()%25==0)g->m[y][x]=7;}if((b==0||b==3)&&x%9==0){for(int j=1;j<5;j++)g->m[h-j][x]=6;for(int i=-2;i<=2;i++)if(x+i>=0&&x+i<W)g->m[h-5][x+i]=6;}}for(int n=0;n<75;n++){int cx=4+rand()%(W-8),cy=37+rand()%20;for(int j=-2;j<=2;j++)for(int i=-3;i<=3;i++)if(i*i+j*j*2<10)g->m[cy+j][cx+i]=0;}}
int32_t terraria_app(void*ctx){UNUSED(ctx);G*g=calloc(1,sizeof(G));if(!g)return -1;g->lock=furi_mutex_alloc(FuriMutexTypeNormal);g->q=furi_message_queue_alloc(32,sizeof(InputEvent));srand(furi_get_tick());world(g);g->x=16;g->y=10;g->dir=1;g->run=true;Gui*gui=furi_record_open(RECORD_GUI);ViewPort*vp=view_port_alloc();view_port_draw_callback_set(vp,draw,g);view_port_input_callback_set(vp,input,g);gui_add_view_port(gui,vp,GuiLayerFullscreen);while(g->run){uint32_t start=furi_get_tick();furi_mutex_acquire(g->lock,FuriWaitForever);InputEvent e;while(furi_message_queue_get(g->q,&e,0)==FuriStatusOk){unsigned bit=1u<<e.key;if(e.type==InputTypeRelease)g->keys&=~bit;if(e.type==InputTypePress){g->keys|=bit;if(g->mode==0){if(e.key==InputKeyUp||e.key==InputKeyDown)g->sel^=1;if(e.key==InputKeyLeft||e.key==InputKeyRight){if(g->sel)g->shirt^=1;else g->hair=(g->hair+(e.key==InputKeyRight?1:2))%3;}if(e.key==InputKeyOk){g->mode=1;g->keys=0;}if(e.key==InputKeyBack)g->run=false;}else if(g->mode==2){if(e.key==InputKeyBack)g->run=false;if(e.key==InputKeyOk){g->mode=1;g->keys=0;}}else if(g->mode==3){if(e.key==InputKeyBack||e.key==InputKeyOk){g->mode=1;g->keys=0;}}else if(e.key==InputKeyBack){g->mode=2;g->keys=0;}}if(e.type==InputTypeLong&&e.key==InputKeyDown&&g->mode==1&&!(g->keys&K(Ok))){g->mode=3;g->keys=0;}}if(g->mode==1){g->t++;int dx=!!(g->keys&K(Right))-!!(g->keys&K(Left));if(dx){g->dir=dx;if(g->t%3==0&&!solid(g,g->x+dx,g->y)&&!solid(g,g->x+dx,g->y-1))g->x+=dx;}if(g->t%3==0){if((g->keys&K(Up))&&solid(g,g->x,g->y+1))g->v=-3;else if(g->v<1)g->v++;int d=g->v<0?-1:1;for(int i=0;i<abs(g->v);i++){if(solid(g,g->x,g->y+d)||(d<0&&solid(g,g->x,g->y+d-1))){g->v=0;break;}g->y+=d;}}if(g->cd>0)g->cd--;if((g->keys&K(Ok))&&!g->cd){int x=g->x+g->dir,y=g->y+1;if(x>=0&&x<W&&y>=0&&y<H){if(g->keys&K(Down)){if(g->stock&&!g->m[y][x]){g->m[y][x]=1;g->stock--;}}else if(g->m[y][x]){g->m[y][x]=0;g->stock++;}}g->cd=6;}}furi_mutex_release(g->lock);view_port_update(vp);uint32_t elapsed=furi_get_tick()-start;if(elapsed<33)furi_delay_ms(33-elapsed);}gui_remove_view_port(gui,vp);view_port_free(vp);furi_record_close(RECORD_GUI);furi_message_queue_free(g->q);furi_mutex_free(g->lock);free(g);return 0;}